using System;
using System.Collections.Generic;
using System.Linq;

public class StranglerRouter
{
    private readonly HashSet<string> _migratedRoutes = new();

    public void RegisterMigratedRoute(string pathPrefix)
    {
        _migratedRoutes.Add(pathPrefix);
    }

    public string RouteRequest(string path)
    {
        if (_migratedRoutes.Any(r => path.StartsWith(r, StringComparison.OrdinalIgnoreCase)))
        {
            return "TARGET: Modern .NET 8 Microservice";
        }

        return "TARGET: Legacy Monolith (Old Server)";
    }
}

public class Program
{
    public static void Main()
    {
        var router = new StranglerRouter();

        Console.WriteLine("--- Sebelum Migrasi Modul Order ---");
        Console.WriteLine($"/api/users   -> {router.RouteRequest("/api/users")}");
        Console.WriteLine($"/api/orders  -> {router.RouteRequest("/api/orders")}");

        Console.WriteLine("\n--- Mendaftarkan Modul /api/orders ke Sistem Baru ---");
        router.RegisterMigratedRoute("/api/orders");

        Console.WriteLine($"/api/users   -> {router.RouteRequest("/api/users")} (Tetap di Legacy)");
        Console.WriteLine($"/api/orders  -> {router.RouteRequest("/api/orders")} (Terkikis ke .NET 8!)");
    }
}

